            if previous:
                if previous['fingerprint'] != fingerprint:
                    raise Rejected('Idempotency key reused with different payload')
                return previous
        symbol = request['symbol']
        if not isinstance(symbol, str) or not re.fullmatch(r'[A-Z][A-Z0-9.]{0,9}', symbol):
